import SwiftUI

/// The notices Apache 2.0 obliges a binary distribution to carry: this app's own LICENSE and
/// NOTICE, and those of every package linked into it (Resources/ThirdPartyNotices.txt,
/// regenerated by `make notices` from Package.resolved).
struct AcknowledgementsView: View {
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        List {
            Section("This app") {
                NavigationLink("Notice") { TextPage(title: "Notice", resource: "NOTICE") }
                NavigationLink("License (Apache 2.0)") { TextPage(title: "License", resource: "LICENSE") }
            }
            Section("Open-source software in this app") {
                NavigationLink("Third-party notices") {
                    TextPage(title: "Third-party notices", resource: "ThirdPartyNotices.txt")
                }
            }
        }
        .navigationTitle("Acknowledgements")
        .toolbar {
            ToolbarItem(placement: .confirmationAction) {
                Button("Done") { dismiss() }
            }
        }
    }
}

private struct TextPage: View {
    let title: String
    let resource: String

    var body: some View {
        ScrollView {
            Text(Self.load(resource))
                .font(.footnote.monospaced())
                .textSelection(.enabled)
                .padding()
                .frame(maxWidth: .infinity, alignment: .leading)
        }
        .navigationTitle(title)
        .navigationBarTitleDisplayMode(.inline)
    }

    static func load(_ resource: String) -> String {
        guard let url = Bundle.main.url(forResource: resource, withExtension: nil),
            let text = try? String(contentsOf: url, encoding: .utf8)
        else {
            return "Missing from this build: \(resource)"
        }
        return text
    }
}
